-- Dr. Lucio C. Tan Building (LCT): ground floor to the 5th floor mezzanine: offices of the basic education
-- department, classrooms 1-31, science and computer laboratories, the canteen, the high school library, the hall
-- with its stage, three stairwells and the elevators.
-- GENERATED by sql/tools/lucio-tan.ps1 from the architectural floor plans. Edit the script and run it again
-- rather than editing this file. Positions are estimates (see the script for the assumptions).
-- Safe to run more than once; keeps the usage log. Run after 06_tan_yan_kee.sql.

USE uenav;

UPDATE building SET description = 'Basic education: offices and canteen on the ground floor, classrooms and laboratories on 2F to 4F, the high school library and a hall with a stage on 5F.' WHERE building_id = 4;
-- the campus door, at the lobby
UPDATE node SET x = 1007, y = 251 WHERE node_id = 29;
UPDATE edge SET distance_m = 9.1 WHERE (from_node_id = 10 AND to_node_id = 29) OR (from_node_id = 29 AND to_node_id = 10);

ON DUPLICATE KEY UPDATE building_id = VALUES(building_id), floor_number = VALUES(floor_number), floor_name = VALUES(floor_name);

-- every walkway inside the building (and its link to the door) is rebuilt below
DELETE FROM edge WHERE from_node_id IN (SELECT node_id FROM (SELECT node_id FROM node WHERE building_id = 4 AND floor_id IS NOT NULL) b)
                  OR to_node_id IN (SELECT node_id FROM (SELECT node_id FROM node WHERE building_id = 4 AND floor_id IS NOT NULL) b);
-- rows from an older run of this script that are no longer made
DELETE FROM node WHERE building_id = 4 AND floor_id IS NOT NULL AND node_id NOT IN (2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044, 2045, 2046, 2047, 2048, 2049, 2050, 2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069, 2070, 2071, 2072, 2073, 2074, 2075, 2076, 2077, 2078, 2079, 2080, 2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088, 2089, 2090, 2091, 2092, 2093, 2094, 2095, 2096, 2097, 2098, 2099, 2100, 2101, 2102, 2103, 2104, 2105, 2106, 2107, 2108, 2109, 2110, 2111, 2112, 2113, 2114, 2115, 2116, 2117, 2118, 2119, 2120, 2121, 2122, 2123, 2124, 2125, 2126, 2127, 2128, 2129, 2130, 2131, 2132, 2133, 2134, 2135, 2136, 2137, 2138, 2139, 2140, 2141, 2142, 2143, 2144, 2145, 2146, 2147, 2148, 2149, 2150, 2151, 2152, 2153, 2154, 2155, 2156, 2157, 2158, 2159, 2160, 2161, 2162, 2163, 2164, 2165, 2166, 2167, 2168, 2169, 2170, 2171, 2172, 2173, 2174, 2175, 2176, 2177, 2178, 2179)
  AND node_id NOT IN (SELECT from_node_id FROM usage_log) AND node_id NOT IN (SELECT to_node_id FROM usage_log);

ON DUPLICATE KEY UPDATE building_id = VALUES(building_id), floor_id = VALUES(floor_id), name = VALUES(name),
  node_type = VALUES(node_type), x = VALUES(x), y = VALUES(y),
  description = IFNULL(node.description, VALUES(description));

ON DUPLICATE KEY UPDATE from_node_id = VALUES(from_node_id), to_node_id = VALUES(to_node_id),
  distance_m = VALUES(distance_m), edge_type = VALUES(edge_type), is_accessible = VALUES(is_accessible);
